            shifted = (ord(char) - offset + shift) % 26
            result.append(chr(offset + shifted))
        else:
            result.append(char)
    return ''.join(result)

def caesar(text, shift):
    result = []
    for char in text:
        if char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            shifted = (ord(char) - base + shift) % 26
            new_char = chr(base + shifted)
            result.append(new_char)
        else:
            result.append(char)
    return "".join(result)

def is_balanced(s):
    stack = []
    pairs = {'(': ')', '[': ']', '{': '}'}
    for char in s:
        if char in pairs:
            stack.append(char)
        elif char in reversed(pairs.values()):
            if not stack:
                return False
            last_open = stack.pop()
            if pairs[last_open] != char:
                return False
    return len(stack) == 0

