def is_balanced(s):
    """
    Check if all brackets in the string are balanced.
    Other characters are ignored.
    """
    stack = []
    bracket_pairs = {')': '(', ']': '[', '}': '{'}
    opening_brackets = set(bracket_pairs.values())

    for char in s:
        if char in opening_brackets:
            stack.append(char)
        elif char in bracket_pairs:
            if stack and stack[-1] == bracket_pairs[char]:
                stack.pop()
            else:
                return False

    return len(stack) == 0

