def rle_encode(s):
    if not s:
        return ""

    result = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            result.append(s[i-1])
            result.append(str(count))
            count = 1

    # Append the last character and its count
    result.append(s[-1])
